@extends('layouts.admin') @section('title','Claims · SwiftFinder') @section('content')<div class="topbar"><div><h1>Claims</h1><div class="muted">Review claims submitted against listings.</div></div></div><form class="filter" method="get"><select name="status"><option value="">All statuses</option>@foreach(['pending','accepted','rejected','cancelled'] as $s)<option value="{{$s}}" @selected(request('status')===$s)>{{$s}}</option>@endforeach</select><button>Filter</button></form><section class="panel"><div class="table-wrap"><table class="table"><tr><th>Item</th><th>Claimant</th><th>Claim</th><th>Status</th><th>Action</th></tr>@forelse($claims as $claim)<tr><td><strong>{{Str::limit($claim->item->title,30)}}</strong><br><span class="muted">{{$claim->item->type}}</span></td><td>{{$claim->claimant->name}}<br><span class="muted">{{$claim->claimant->email}}</span></td><td>{{Str::limit($claim->message,100)}}</td><td><span class="badge {{$claim->status==='accepted'?'success':($claim->status==='pending'?'warn':'danger')}}">{{$claim->status}}</span></td><td>@if($claim->status==='pending')<form class="inline" method="post" action="{{route('admin.claims.update',$claim)}}">@csrf @method('PATCH')<button name="status" value="accepted">Accept</button><button class="danger" name="status" value="rejected">Reject</button></form>@else<span class="muted">Reviewed</span>@endif</td></tr>@empty<tr><td colspan="5" class="muted">No claims found.</td></tr>@endforelse</table></div>{{$claims->withQueryString()->links()}}</section>@endsection
